import java.util.ArrayDeque;
import java.util.Queue;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

public class Main {
    // 1) 可重入：同一 owner 多次 lock 递增 state，逐层 unlock
    static final class SafeCounter {
        private final ReentrantLock lock = new ReentrantLock();
        private int value;

        void incrementTwice() {
            lock.lock();
            try {
                value++;
                nestedIncrement(); // 重入：同一 owner 递增 state
            } finally {
                lock.unlock();
            }
        }

        private void nestedIncrement() {
            lock.lock();
            try {
                assert lock.getHoldCount() == 2 : "重入后层数应为 2";
                value++;
            } finally {
                lock.unlock();
            }
        }

        int get() {
            lock.lock();
            try {
                return value;
            } finally {
                lock.unlock();
            }
        }
    }

    // 2) Condition 多条件队列：notFull 唤醒生产者，notEmpty 唤醒消费者
    static final class BoundedBox {
        private final ReentrantLock lock = new ReentrantLock();
        private final Condition notFull = lock.newCondition();
        private final Condition notEmpty = lock.newCondition();
        private final Queue<Integer> queue = new ArrayDeque<>();
        private final int capacity;

        BoundedBox(int capacity) { this.capacity = capacity; }

        void put(int value) throws InterruptedException {
            lock.lockInterruptibly();
            try {
                while (queue.size() == capacity) {
                    notFull.await(); // 释放锁，进 notFull 条件队列
                }
                queue.add(value);
                notEmpty.signal(); // 唤醒一个消费者
            } finally {
                lock.unlock();
            }
        }

        int take() throws InterruptedException {
            lock.lockInterruptibly();
            try {
                while (queue.isEmpty()) {
                    notEmpty.await(); // 释放锁，进 notEmpty 条件队列
                }
                int value = queue.remove();
                notFull.signal(); // 唤醒一个生产者
                return value;
            } finally {
                lock.unlock();
            }
        }
    }

    public static void main(String[] args) throws Exception {
        // --- 重入验证 ---
        SafeCounter counter = new SafeCounter();
        int threads = 4, rounds = 10_000;
        CountDownLatch done = new CountDownLatch(threads);
        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                for (int j = 0; j < rounds; j++) counter.incrementTwice();
                done.countDown();
            }, "counter-" + i).start();
        }
        done.await();
        assert counter.get() == threads * rounds * 2 : "重入计数错误";
        System.out.println("重入验证: counter=" + counter.get());

        // --- tryLock 超时：持锁线程 sleep 180ms，等待方只给 80ms 预算 ---
        ReentrantLock busy = new ReentrantLock();
        CountDownLatch locked = new CountDownLatch(1);
        Thread holder = new Thread(() -> {
            busy.lock();
            try {
                locked.countDown();
                Thread.sleep(180);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } finally {
                busy.unlock();
            }
        }, "busy-holder");
        holder.start();
        locked.await();
        boolean acquired = busy.tryLock(80, TimeUnit.MILLISECONDS);
        System.out.println("tryLock 超时: acquired=" + acquired);
        assert !acquired : "80ms 预算内拿不到锁";
        if (acquired) busy.unlock();
        holder.join();

        // --- lockInterruptibly：等待期间被中断 ---
        ReentrantLock interruptible = new ReentrantLock();
        CountDownLatch waiting = new CountDownLatch(1);
        interruptible.lock();
        Thread waiter = new Thread(() -> {
            try {
                waiting.countDown();
                interruptible.lockInterruptibly(); // 等待期间可响应中断
                throw new AssertionError("不应到达这里");
            } catch (InterruptedException expected) {
                System.out.println("lockInterruptibly: 被中断，未拿到锁");
                Thread.currentThread().interrupt();
            }
        }, "interruptible-waiter");
        waiter.start();
        waiting.await();
        Thread.sleep(50);
        waiter.interrupt();
        waiter.join();
        interruptible.unlock();

        // --- Condition 有界队列 ---
        BoundedBox box = new BoundedBox(1);
        Thread consumer = new Thread(() -> {
            try {
                System.out.println("Condition take=" + box.take());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }, "box-consumer");
        consumer.start();
        Thread.sleep(50);
        box.put(42);
        consumer.join();
    }
}
